&reftitle.changelog;







     &Version;
     &Description;





     8.3.0
     अब token नदिइएमा E_WARNING emit गर्दछ।

  &reftitle.examples;



    strtok को उदाहरण


<?php
$string = "This is\tan example\nstring";
/* Use tab and newline as tokenizing characters as well  */
$tok = strtok($string, " \n\t");

while ($tok !== false) {
    echo "Word={$tok}\n";
    $tok = strtok(" \n\t");
}
?>







    खाली भाग फेला पर्दा strtok को व्यवहार


<?php
$first_token  = strtok('/something', '/');
$second_token = strtok('/');
var_dump($first_token, $second_token);
?>


    &example.outputs;


string(9) "something"
bool(false)







    strtok र explode बीचको भिन्नता


<?php
$string = ";aaa;;bbb;";

$parts = [];
$tok = strtok($string, ";");
while ($tok !== false) {
    $parts[] = $tok;
    $tok = strtok(";");
}
echo json_encode($parts),"\n";

$parts = explode(";", $string);
echo json_encode($parts),"\n";


    &example.outputs;


["aaa","bbb"]
["","aaa","","bbb",""]
